<header class="mb-4 d-flex justify-content-between align-items-start"><div><h1>Notifications</h1><p>Review company notices and required communications.</p></div><?php if($canCreateNotice??false): ?><a class="btn btn-primary" href="/company-notices/create">Create Notice</a><?php endif; ?></header>
